import{_ as t,c as o,o as n,a3 as r}from"./chunks/framework.BurWKwwG.js";const m=JSON.parse('{"title":"Network Analysis","description":"","frontmatter":{},"headers":[],"relativePath":"3.5_network.md","filePath":"3.5_network.md"}'),a={name:"3.5_network.md"};function i(s,e,l,d,h,c){return n(),o("div",null,e[0]||(e[0]=[r('<h1 id="network-analysis" tabindex="-1">Network Analysis <a class="header-anchor" href="#network-analysis" aria-label="Permalink to “Network Analysis”">​</a></h1><p>The <a href="/network">Network Analysis</a> page (<code>/network</code>) provides interactive exploration and statistical analysis of protein-protein interaction (PPI) networks, powered by the <a href="https://string-db.org" target="_blank" rel="noreferrer">STRING</a> database (v12.0) and rendered with Cytoscape.js.</p><h2 id="workflow-overview" tabindex="-1">Workflow Overview <a class="header-anchor" href="#workflow-overview" aria-label="Permalink to “Workflow Overview”">​</a></h2><ol><li><strong>Build</strong> — enter proteins (or load them), set parameters, and click <em>Generate Network</em></li><li><strong>Expand</strong> — grow the network with high-confidence interaction partners</li><li><strong>Analyze</strong> — topology, enrichment, modules, proximity testing and set comparison</li><li><strong>Download</strong> — export publication-ready images and a complete, reproducible analysis bundle</li></ol><h2 id="building-a-network" tabindex="-1">Building a Network <a class="header-anchor" href="#building-a-network" aria-label="Permalink to “Building a Network”">​</a></h2><h3 id="input-methods" tabindex="-1">Input Methods <a class="header-anchor" href="#input-methods" aria-label="Permalink to “Input Methods”">​</a></h3><table tabindex="0"><thead><tr><th>Method</th><th>Description</th></tr></thead><tbody><tr><td><strong>Manual Input</strong></td><td>Type protein names/gene symbols, one per line</td></tr><tr><td><strong>From Database</strong></td><td>Select proteins curated in the CBD database</td></tr><tr><td><strong>File Upload</strong></td><td>Upload a <code>.txt</code>/<code>.csv</code> file with one protein per line</td></tr></tbody></table><p>Before the network is built, an <strong>ID mapping report</strong> resolves your input against STRING and reports any names that could not be matched.</p><h3 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h3><ul><li><strong>Species</strong> — all 12,000+ STRING species are supported (searchable list). Local-index features (instant expansion, proximity test) are human-only.</li><li><strong>Confidence Score</strong> — minimum combined score (0–1000) for an interaction to be included; 400 corresponds to medium confidence (STRING default).</li><li><strong>Network Type</strong> — <em>Functional</em> aggregates all evidence channels; <em>Physical</em> keeps only direct physical binding.</li><li><strong>Edge Coloring</strong> — <em>Confidence</em> (gray gradient by combined score) or <em>Evidence</em> (color by dominant evidence channel, with an on-graph legend).</li><li><strong>Hide disconnected nodes</strong> — removes proteins left without visible edges.</li></ul><h2 id="network-expansion" tabindex="-1">Network Expansion <a class="header-anchor" href="#network-expansion" aria-label="Permalink to “Network Expansion”">​</a></h2><p><em>First-shell Partners</em> adds the top-scoring STRING interaction partners of each protein in the current network (0–20 per protein).</p><ul><li><strong>Human</strong> networks use a bundled local STRING index (combined score ≥ 400) — expansion is instant and works even when string-db.org is unreachable from the server.</li><li>Other species are expanded through the live STRING API.</li><li>Expanding recomputes statistics and topology; module, proximity and path results are reset because the network changed. Apply repeatedly to grow the network further.</li></ul><h2 id="visualization" tabindex="-1">Visualization <a class="header-anchor" href="#visualization" aria-label="Permalink to “Visualization”">​</a></h2><ul><li><strong>Layouts</strong> — cycle through force-directed (cose-bilkent), cose, circular, grid, breadth-first and concentric arrangements; zoom and pan supported.</li><li><strong>Evidence channel legend</strong> — displayed when edge coloring is set to <em>Evidence</em>.</li><li><strong>Node / edge dialogs</strong> — click a node for its degree, centrality values, module membership and lazily loaded <strong>functional annotations</strong>; click an edge for its confidence score, dominant evidence channel and lazily loaded <strong>supporting publications</strong> (Europe PMC co-citation search, linked to PubMed).</li><li><strong>View in CBD</strong> — jump from a network node to the matching biomarker entry in the CBD database.</li><li><strong>Shortest path finder</strong> — highlight the route connecting any two proteins of the network.</li></ul><h3 id="color-schemes" tabindex="-1">Color Schemes <a class="header-anchor" href="#color-schemes" aria-label="Permalink to “Color Schemes”">​</a></h3><p>The default <strong>Morandi · Light</strong> palette (muted, low-saturation tones) can be switched to <strong>Morandi · Classic</strong> or <strong>Classic</strong>, or fully customized: pick the node color and the 15 module colors yourself. The choice is stored in the browser and applied live. Modules beyond the palette receive automatically generated distinct colors.</p><h2 id="analysis-tabs" tabindex="-1">Analysis Tabs <a class="header-anchor" href="#analysis-tabs" aria-label="Permalink to “Analysis Tabs”">​</a></h2><h3 id="topology" tabindex="-1">Topology <a class="header-anchor" href="#topology" aria-label="Permalink to “Topology”">​</a></h3><p>Sortable table of per-protein metrics:</p><table tabindex="0"><thead><tr><th>Metric</th><th>Meaning</th></tr></thead><tbody><tr><td>Degree</td><td>Number of connections within the network</td></tr><tr><td>Betweenness</td><td>Number of shortest paths passing through the node (bridge/hub importance)</td></tr><tr><td>Closeness</td><td>Inverse average distance to all other nodes</td></tr><tr><td>Clustering</td><td>How interconnected a protein&#39;s neighbours are (1 = complete neighbourhood)</td></tr></tbody></table><p>The tab also provides the <strong>live edge filter</strong> (hide edges below a confidence threshold without refetching) and the <strong>shortest path finder</strong>.</p><h3 id="enrichment" tabindex="-1">Enrichment <a class="header-anchor" href="#enrichment" aria-label="Permalink to “Enrichment”">​</a></h3><p>Over-representation analysis computed by STRING, grouped by category (GO Process/Function/Component, KEGG, Reactome, WikiPathways, HPO, DISEASES, PMID and more). Columns: Term (linked), Description, Genes (input proteins in the term), P-value and FDR — judge significance by FDR.</p><h3 id="modules" tabindex="-1">Modules <a class="header-anchor" href="#modules" aria-label="Permalink to “Modules”">​</a></h3><p>Community detection with the <strong>Louvain algorithm</strong>. Nodes are colored by module; the table reports module size, internal edges and density, with actions to <strong>isolate</strong> a module in the graph or run <strong>module-level enrichment</strong>.</p><h3 id="proximity-test" tabindex="-1">Proximity Test <a class="header-anchor" href="#proximity-test" aria-label="Permalink to “Proximity Test”">​</a></h3><p>Statistical test of whether your protein set is more interconnected than expected by chance, run on the local human STRING network (combined score ≥ 400) with degree-matched randomization:</p><ul><li><strong>Cohesion</strong> — internal edge count of your set vs. random sets (primary statistic); report z-score and empirical p-value with a permutation histogram</li><li><strong>Proximity</strong> — mean shortest distance within your set vs. random sets (Menche-style)</li><li>Interpretation: z &gt; 2 and p &lt; 0.05 indicate a functionally cohesive, non-random protein set</li></ul><h3 id="compare" tabindex="-1">Compare <a class="header-anchor" href="#compare" aria-label="Permalink to “Compare”">​</a></h3><p>Enter two protein sets (A and B) to build their union network, colored by membership — clay (A only), dusty blue (B only), mauve (shared) — with overlap statistics and the <strong>Jaccard index</strong> |A∩B| / |A∪B|.</p><h2 id="downloading-results" tabindex="-1">Downloading Results <a class="header-anchor" href="#downloading-results" aria-label="Permalink to “Downloading Results”">​</a></h2><table tabindex="0"><thead><tr><th>Button</th><th>Content</th></tr></thead><tbody><tr><td><strong>PNG / SVG</strong></td><td>The styled network exactly as shown (current colors and layout)</td></tr><tr><td><strong>GraphML</strong></td><td>The network for import into Cytoscape desktop, including topology attributes</td></tr><tr><td><strong>Download All</strong></td><td>Complete analysis bundle: displayed edges (TSV, with evidence channel scores), enrichment table (TSV), module assignments (TSV), the GraphML file, and a full JSON snapshot of every analysis and parameter</td></tr></tbody></table><p>The bundle is generated from the current in-memory state — no re-fetching — so downloaded files always match what is on screen.</p><h2 id="implementation-notes" tabindex="-1">Implementation Notes <a class="header-anchor" href="#implementation-notes" aria-label="Permalink to “Implementation Notes”">​</a></h2><ul><li>Network and enrichment data are proxied through the CBD backend (never fetched directly from the browser)</li><li>The local human STRING index (<code>combined score ≥ 400</code>, ~19.5k proteins / ~465k edges) also powers the PRS network features</li><li>Literature search is provided by <a href="https://europepmc.org" target="_blank" rel="noreferrer">Europe PMC</a></li></ul>',36)]))}const g=t(a,[["render",i]]);export{m as __pageData,g as default};
